import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1791960929000}'),o={name:"guide/getting-started.md"};function i(n,t,d,l,h,g){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>SSPL Billing is a fast billing and back-office screen set that runs in your web browser on top of ERPNext. This guide walks through the daily flow for each role.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A modern browser — Chrome or Edge recommended</li><li>The address of your SSPL Billing site, given by your administrator</li><li>A user name and password</li></ul><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><ol><li>Open your SSPL Billing address in the browser.</li><li>Enter your user name (usually your email) and password.</li><li>Press <strong>Enter</strong>. You land on the <strong>Dashboard</strong>.</li></ol><p>If you open a screen without logging in, you are sent back to the login page automatically.</p><div class="tip custom-block"><p class="custom-block-title">First load takes a few seconds</p><p>On the first login of the day the Dashboard downloads items and customers into the browser so that search is instant afterwards. Wait for the sync to finish before you start billing.</p></div><h2 id="who-does-what" tabindex="-1">Who does what <a class="header-anchor" href="#who-does-what" aria-label="Permalink to &quot;Who does what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Main screens</th></tr></thead><tbody><tr><td><strong>Biller</strong></td><td>Sales Invoice, Quotation, Sales Order, Customer Enquiry</td></tr><tr><td><strong>Cashier</strong></td><td>Cashier Desk, Cashier Management, Payment Receipt</td></tr><tr><td><strong>Purchase / store</strong></td><td>Purchase Invoice, Purchase Desk, Store Transfer, Repack, Stock Reconciliation</td></tr><tr><td><strong>Accounts</strong></td><td>Ledgers, Journal / Contra, Cheque Register, GST Ledger, Reports</td></tr><tr><td><strong>Administrator</strong></td><td>User access, Billing Settings, Naming Settings, HRMS</td></tr></tbody></table><p>Your administrator decides exactly which screens you see — see <a href="./admin">Users, access &amp; settings</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./dashboard">Dashboard &amp; navigation</a></li><li><a href="./sales">Sales &amp; billing</a></li><li><a href="./shortcuts">Keyboard shortcuts</a></li></ul>',13)])])}const p=e(o,[["render",i]]);export{u as __pageData,p as default};
